CREATE TABLE IF NOT EXISTS usuarios(id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, correo TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, rol TEXT NOT NULL CHECK(rol IN ('estudiante','docente')), activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN (0,1)), intentos_fallidos INTEGER NOT NULL DEFAULT 0, bloqueado_hasta TEXT, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cursos(id INTEGER PRIMARY KEY, docente_id INTEGER NOT NULL REFERENCES usuarios(id), titulo TEXT NOT NULL COLLATE NOCASE, descripcion TEXT NOT NULL, categoria TEXT NOT NULL, nivel TEXT NOT NULL CHECK(nivel IN ('Básico','Intermedio','Avanzado')), estado TEXT NOT NULL DEFAULT 'activo' CHECK(estado IN ('activo','inactivo')), imagen_portada TEXT, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(docente_id,titulo));
CREATE TABLE IF NOT EXISTS materiales(id INTEGER PRIMARY KEY, curso_id INTEGER NOT NULL REFERENCES cursos(id), tipo TEXT NOT NULL CHECK(tipo IN ('pdf','video')), titulo TEXT NOT NULL, archivo_ruta TEXT, tamano_bytes INTEGER CHECK(tamano_bytes BETWEEN 0 AND 10485760), url TEXT, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((tipo='pdf' AND archivo_ruta IS NOT NULL AND tamano_bytes IS NOT NULL AND url IS NULL) OR (tipo='video' AND url IS NOT NULL AND archivo_ruta IS NULL)));
CREATE TABLE IF NOT EXISTS inscripciones(id INTEGER PRIMARY KEY, estudiante_id INTEGER NOT NULL REFERENCES usuarios(id), curso_id INTEGER NOT NULL REFERENCES cursos(id), fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, estado TEXT NOT NULL DEFAULT 'activa' CHECK(estado='activa'), UNIQUE(estudiante_id,curso_id));
CREATE TABLE IF NOT EXISTS evaluaciones(id INTEGER PRIMARY KEY, curso_id INTEGER NOT NULL REFERENCES cursos(id), titulo TEXT NOT NULL, descripcion TEXT NOT NULL DEFAULT '', fecha_inicio TEXT NOT NULL, fecha_limite TEXT NOT NULL, duracion_min INTEGER NOT NULL CHECK(duracion_min>0), estado TEXT NOT NULL DEFAULT 'borrador' CHECK(estado IN ('borrador','publicada')), puntaje_maximo INTEGER NOT NULL DEFAULT 500 CHECK(puntaje_maximo=500), CHECK(fecha_inicio<fecha_limite));
CREATE TABLE IF NOT EXISTS preguntas(id INTEGER PRIMARY KEY, evaluacion_id INTEGER NOT NULL REFERENCES evaluaciones(id) ON DELETE CASCADE, enunciado TEXT NOT NULL, puntaje INTEGER NOT NULL CHECK(puntaje>0), orden INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS opciones(id INTEGER PRIMARY KEY, pregunta_id INTEGER NOT NULL REFERENCES preguntas(id) ON DELETE CASCADE, texto TEXT NOT NULL, es_correcta INTEGER NOT NULL CHECK(es_correcta IN (0,1)));
CREATE TABLE IF NOT EXISTS entregas(id INTEGER PRIMARY KEY, evaluacion_id INTEGER NOT NULL REFERENCES evaluaciones(id), estudiante_id INTEGER NOT NULL REFERENCES usuarios(id), iniciada_en TEXT NOT NULL, enviada_en TEXT, nota INTEGER CHECK(nota BETWEEN 0 AND 500), estado TEXT NOT NULL DEFAULT 'en_curso' CHECK(estado IN ('en_curso','enviada')), UNIQUE(evaluacion_id,estudiante_id));
CREATE TABLE IF NOT EXISTS respuestas(id INTEGER PRIMARY KEY, entrega_id INTEGER NOT NULL REFERENCES entregas(id), pregunta_id INTEGER NOT NULL REFERENCES preguntas(id), opcion_id INTEGER REFERENCES opciones(id), es_correcta INTEGER NOT NULL, puntaje_obtenido INTEGER NOT NULL, UNIQUE(entrega_id,pregunta_id));
